const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');
const W=1100,H=530,G=416;canvas.width=W;canvas.height=H;
let state='ready',score=0,best=0,time=0,scroll=0,speed=450,spawn=1.4,coinTimer=.4,specialTimer=7,boost=0,boostCoins=0,obstacles=[],coins=[],sparks=[],last=0;
const hero={x:170,y:G,vy:0,jumps:0};
try{best=Number(localStorage.getItem('chiikawa-run-score-v2'))||0}catch{}$('best').textContent=best;
function panel(t,m,b){$('title').textContent=t;$('message').innerHTML=m;$('start').textContent=b;$('overlay').classList.remove('hidden')}
function begin(){state='playing';score=0;time=0;scroll=0;speed=450;spawn=1.5;coinTimer=.2;specialTimer=7;boost=0;boostCoins=0;obstacles=[];coins=[];sparks=[];Object.assign(hero,{y:G,vy:0,jumps:0});$('score').textContent=0;$('pause').textContent='Ⅱ';$('overlay').classList.add('hidden');hud()}
function jump(){if(state!=='playing'||boost>0||hero.jumps>=2)return;hero.vy=hero.jumps===0?-760:-700;hero.jumps++;if(hero.jumps===2)hero.spinAt=time;burst(hero.x+25,hero.y-8,hero.jumps===2?'#b19bfa':'#ffffff',12)}
function toggle(){if(state==='playing'){state='paused';$('pause').textContent='▶';panel('잠깐 쉬어 갈까요?','점프도 피버 시간도 잠시 멈췄어요.','계속 달리기 →')}else if(state==='paused'){state='playing';$('pause').textContent='Ⅱ';$('overlay').classList.add('hidden')}}
$('start').onclick=e=>{e.stopPropagation();state==='paused'?toggle():begin()};$('pause').onclick=e=>{e.stopPropagation();toggle()};$('game').addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;if(state==='playing'){e.preventDefault();jump()}});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp'].includes(e.code)){e.preventDefault();if(e.repeat)return;if(state==='ready'||state==='over')begin();else jump()}if(e.code==='KeyP'&&!e.repeat)toggle()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')toggle()});
function hud(){$('score').textContent=score.toLocaleString();$('power').textContent=boost>0?`🌈 피버 ${boost.toFixed(1)}초 · 무적 + 자동 수집`:`${hero.jumps}/2 점프 · 코인을 모으세요`;}
function burst(x,y,color,n=8){for(let i=0;i<n;i++)sparks.push({x,y,vx:(Math.random()-.5)*250,vy:(Math.random()-.5)*220,life:.5,color})}
function collect(c){if(c.taken)return;c.taken=true;const points=c.type==='special'?300:c.type==='star'?100:10;score+=points;burst(c.x,c.y,c.type==='special'?'#b99cff':'#ffcd48');if(c.type==='special'){boost=5;boostCoins=0;hero.vy=0;hero.jumps=0;obstacles=[];coins=[]}hud()}
function end(){state='over';if(score>best){best=score;$('best').textContent=best.toLocaleString();try{localStorage.setItem('chiikawa-run-score-v2',best)}catch{}}panel('우와! 잘 달렸어요',`이번 점수 <b>${score.toLocaleString()}점</b> · 최고 ${best.toLocaleString()}점<br>별 코인과 무지개 코인으로 더 높이!`,'다시 도전 →')}
function update(dt){time+=dt;const wasBoost=boost>0;boost=Math.max(0,boost-dt);speed=wasBoost?1000:Math.min(650,450+time*2);scroll+=speed*dt;
 if(wasBoost){hero.y+=(177+Math.sin(time*9)*8-hero.y)*Math.min(1,dt*12);hero.vy=0;hero.jumps=0;boostCoins-=dt;if(boostCoins<=0){boostCoins=.075;coins.push({x:W+30,y:145+Math.sin(time*8)*27,type:Math.random()<.2?'star':'normal'})}if(boost===0){obstacles=[];spawn=1.6;hero.vy=0;coinTimer=.2;specialTimer=10}}
 else{hero.vy+=2050*dt;hero.y+=hero.vy*dt;if(hero.y>=G){hero.y=G;hero.vy=0;hero.jumps=0}spawn-=dt;if(spawn<=0){obstacles.push({x:W+65,w:48,h:Math.random()<.5?60:78,type:Math.random()<.5?'mushroom':'cake'});spawn=1.15+Math.random()*.6}coinTimer-=dt;if(coinTimer<=0){const height=[G-40,G-115,G-215][Math.floor(Math.random()*3)];for(let i=0;i<6;i++)coins.push({x:W+55+i*53,y:height-Math.sin(i/5*Math.PI)*27,type:i===3&&Math.random()<.6?'star':'normal'});coinTimer=1.6}specialTimer-=dt;if(specialTimer<=0){coins.push({x:W+60,y:G-110,type:'special'});specialTimer=13}}
 for(const c of coins){c.x-=speed*dt;if(wasBoost&&c.x<hero.x+300){c.x+=(hero.x+28-c.x)*Math.min(1,dt*16);c.y+=(hero.y-38-c.y)*Math.min(1,dt*16)}if(!c.taken&&c.x>hero.x-22&&c.x<hero.x+78&&Math.abs(c.y-(hero.y-40))<52)collect(c)}coins=coins.filter(c=>!c.taken&&c.x>-40);
 for(const o of obstacles){o.x-=speed*dt;if(!wasBoost&&hero.x+57>o.x+7&&hero.x+5<o.x+o.w-6&&hero.y-5>G-o.h+9){end();break}}obstacles=obstacles.filter(o=>o.x>-100);for(const s of sparks){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt}sparks=sparks.filter(s=>s.life>0);hud()}
function round(x,y,w,h,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function ellipse(x,y,rx,ry,c,outline=false){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();if(outline){ctx.strokeStyle='#66515b';ctx.lineWidth=2.5;ctx.stroke()}}
function star(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rad=i%2?r*.46:r;ctx.lineTo(x+Math.cos(a)*rad,y+Math.sin(a)*rad)}ctx.closePath();ctx.fill()}
function background(){const gradient=ctx.createLinearGradient(0,0,0,H);gradient.addColorStop(0,boost>0?'#b6b5f4':'#c1e5f0');gradient.addColorStop(1,'#fff1dd');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);ellipse(900,96,43,43,'#ffdea0');for(let i=0;i<7;i++){const x=((i*205-scroll*.12)%(W+220)+W+220)%(W+220)-90,y=77+i%3*43;ellipse(x,y,44,18,'#ffffffbb');ellipse(x+25,y-8,30,23,'#ffffffbb')}
 for(let i=-1;i<7;i++){const x=i*240-scroll*.23%240;ellipse(x,400,200,155,i%2?'#c6dfd0':'#d2e8d9');const hx=x+50;round(hx,300,83,89,17,'#fff4db');ctx.fillStyle='#d7a7be';ctx.beginPath();ctx.moveTo(hx-12,309);ctx.quadraticCurveTo(hx+40,220,hx+96,309);ctx.fill();round(hx+30,345,23,44,12,'#bd9fab');ellipse(hx+17,327,8,8,'#e9c584')}
 round(0,G,W,115,0,'#efcfbc');round(0,G,W,15,0,'#b6d59f');round(0,G+15,W,7,0,'#d3b799');for(let i=-1;i<22;i++){const x=i*65-scroll%65;ellipse(x,G+50,4,3,'#fff0dd');star(x+30,G+84,4,'#d9b39f')}
 if(boost>0){ctx.strokeStyle='#ffffff70';ctx.lineWidth=3;for(let i=0;i<20;i++){const x=(i*113-scroll*1.6)%1300,y=85+i*17;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+70,y);ctx.stroke()}}}
function drawHero(){ctx.save();ctx.translate(hero.x+29,hero.y);const flying=boost>0,bob=hero.y===G?Math.sin(time*24)*2:0;ctx.translate(0,bob);if(flying){for(let i=5;i>=0;i--)round(-75-i*23,-53+i*3,90,8,4,['#ffacc9','#ffd899','#fff3a4','#b5e7b7','#9dd9f1','#c6b0f4'][i]);star(-40,-65,8,'#fff2ab')}
 const step=hero.y===G?Math.sin(time*25)*5:0;ellipse(-13,-6+step,10,7,'#fffaf3',true);ellipse(14,-6-step,10,7,'#fffaf3',true);ellipse(0,-25,26,24,'#fffaf3',true);ellipse(-24,-73,12,13,'#fffaf3',true);ellipse(24,-73,12,13,'#fffaf3',true);ellipse(-24,-73,6,6,'#f4cbd5');ellipse(24,-73,6,6,'#f4cbd5');ellipse(0,-48,35,31,'#fffaf3',true);ellipse(-14,-51,4,5,'#493e43');ellipse(14,-51,4,5,'#493e43');ellipse(-15,-53,1.3,1.5,'white');ellipse(13,-53,1.3,1.5,'white');ellipse(-24,-40,8,5,'#f2b8c9');ellipse(24,-40,8,5,'#f2b8c9');ctx.strokeStyle='#66515b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-6,-40);ctx.quadraticCurveTo(-3,-34,0,-39);ctx.quadraticCurveTo(3,-34,6,-40);ctx.stroke();ellipse(-27,-22,8,6,'#fffaf3',true);ellipse(27,-25,8,6,'#fffaf3',true);ctx.restore()}
function drawCoin(c){const pulse=1+Math.sin(time*6+c.x*.01)*.08;ctx.save();ctx.translate(c.x,c.y);ctx.scale(pulse,pulse);if(c.type==='special'){ctx.shadowColor='#b091ed';ctx.shadowBlur=22;ellipse(0,0,23,23,'#c6acf5');ellipse(0,0,17,17,'#f7eaff');star(0,0,13,'#b08ce4');for(let i=0;i<3;i++)star(Math.cos(time*3+i*2.1)*31,Math.sin(time*3+i*2.1)*31,4,['#ffb2d2','#ffdd72','#a4dce7'][i])}else if(c.type==='star'){ellipse(0,0,19,19,'#f3a847');star(0,0,15,'#fff2a5')}else{ellipse(0,0,13,15,'#eab34a');ellipse(0,-1,10,12,'#ffe28a');round(-2,-8,4,14,2,'#dfab41')}ctx.restore()}
function drawObstacle(o){if(o.type==='mushroom'){round(o.x+13,G-39,24,39,8,'#fff1d7');ellipse(o.x+24,G-o.h+20,31,23,'#d993a8');ellipse(o.x+12,G-o.h+15,6,5,'#fff4e4');ellipse(o.x+36,G-o.h+21,7,5,'#fff4e4')}else{round(o.x,G-o.h,o.w,o.h,8,'#d7a880');round(o.x-3,G-o.h,o.w+6,16,7,'#fff0dc');ellipse(o.x+24,G-o.h-6,9,11,'#e58f9f');for(let j=0;j<3;j++)round(o.x+6+j*15,G-25,5,12,3,'#b88870')}}
function frame(now){const dt=Math.min((now-last)/1000||0,.033);last=now;if(state==='playing')update(dt);background();ellipse(hero.x+30,G+3,34,5,'#94718e33');coins.forEach(drawCoin);obstacles.forEach(drawObstacle);drawHero();for(const s of sparks)star(s.x,s.y,5*s.life/.5,s.color);requestAnimationFrame(frame)}requestAnimationFrame(frame);
